(41, 'Emergency Medicine Express Delivery', 'Purchase prescribed medicine from Labaid Pharmacy Badda and deliver to residence in Middle Badda within 90 minutes. Cost of medicine reimbursed in cash on delivery.', 24, 7, 'physical', 'Middle Badda, near Post Office', 'Badda', 'Dhaka', 250, 60, 50, 450, NULL, 5, 14, '💊', 'delivery,errand,medicine,badda', 'open', 1, 1, 3),
(42, 'DU Transcript Document Collection', 'Collect sealed academic transcript envelope from Dhaka University Administrative Building and courier it via Sundarban Courier to Chittagong. Authorization letter provided.', 25, 8, 'physical', 'DU Registrar Building, Nilkhet', 'Nilkhet', 'Dhaka', 350, 90, 50, 450, NULL, 4.9, 18, '📜', 'document,du,nilkhet,errand', 'open', 0, 0, 24),
(40, 'Used Motorbike Physical Condition Check', 'Inspect a secondhand Yamaha FZ motorbike at Tejgaon showroom. Photograph tire tread depth, engine sound video, and odometer reading for remote buyer verification.', 26, 9, 'physical', 'Tejgaon Industrial Area, near Nabikok', 'Tejgaon', 'Dhaka', 450, 45, 50, 450, NULL, 4.7, 9, '🏍️', 'inspection,motorbike,tejgaon,auto', 'open', 0, 0, 24),
(39, 'Apartment Physical Inspection & Video Tour', 'Visit a 3-bedroom rental apartment in Uttara Sector 11. Record a 5-minute continuous 4K video tour, check water tap pressure, and photograph any wall dampness.', 28, 7, 'physical', 'Road 14, Sector 11, Uttara', 'Uttara', 'Dhaka', 500, 60, 50, 450, NULL, 5, 12, '🏠', 'apartment,inspection,uttara,video', 'open', 1, 1, 24),
(14, 'Take Photos of 5 Shops (Dhanmondi)', 'Visit 5 clothing shops in Dhanmondi 27 and take 3 clear photos of each storefront with visible signboards. Note the shop names. Photos must be original (GPS-stamped if possible).', 29, 10, 'physical', 'In front of Anam Rangs Plaza, Dhanmondi 27', 'Dhanmondi', 'Dhaka', 300, 60, 50, 450, NULL, 4.8, 17, '📷', 'photo,local,shop,dhanmondi', 'open', 1, 0, 48),
(18, 'Verify Shop Signboard QR Codes', 'Check 8 partner shops in Mirpur 10 to confirm our promotional QR standees are placed correctly and scan properly. Fill the mobile checklist and photo each standee.', 30, 8, 'physical', 'Mirpur 10 roundabout area', 'Mirpur', 'Dhaka', 150, 30, 50, 450, NULL, 4.5, 13, '✅', 'verification,qr,local,mirpur', 'open', 0, 0, 24),
(38, 'Storefront Audit & Trade License Photo', 'Visit 3 retail cosmetics outlets near GEC Circle, Chittagong. Capture high-res photos of storefront signboard, business card, and trade license on display.', 30, 10, 'physical', 'GEC Circle, Nasirabad', 'GEC Circle', 'Chattogram', 350, 45, 50, 450, NULL, 4.9, 8, '🏢', 'audit,chittagong,gec,store photo', 'open', 1, 0, 24),
(17, 'Distribute Flyers at Trade Fair', 'Distribute 500 promotional flyers to visitors at the Dhaka Trade Fair grounds for 3 hours. Friendly presentation matters. Uniform t-shirt will be provided.', 31, 10, 'physical', 'Bangabandhu Bangladesh-China Friendship Exhibition Center, Agargaon', 'Agargaon', 'Dhaka', 400, 180, 50, 450, NULL, 4.7, 9, '📣', 'physical,event,flyers,agargaon', 'open', 0, 0, 48),
(19, 'Event Support: Product Launch Day', 'Support our product launch booth at Gulshan for 6 hours: greet guests, hand out samples, manage the demo table. Well-groomed, fluent in Bangla/English. Breakfast + lunch included.', 31, 10, 'physical', 'Gulshan 1 Circle, in front of the venue', 'Gulshan', 'Dhaka', 2000, 360, 50, 450, NULL, 4.9, 5, '🎪', 'physical,event,gulshan,booth', 'open', 1, 1, 24),
(43, 'Optical Fiber Router Setup & Speed Test', 'Configure a new TP-Link Dual Band Gigabit router at residential flat in Banani. Run speed test on 5GHz band and ensure coverage in master bedroom. Report screenshots.', 36, 9, 'physical', 'Road 11, Block D, Banani', 'Banani', 'Dhaka', 300, 45, 50, 450, NULL, 4.8, 21, '📶', 'wifi,router,setup,banani', 'open', 0, 0, 12),
(10, 'Market Research Survey', 'Complete a 15-minute consumer habits survey about tea brands. Honest answers required. Payment released after quality check.', 38, 10, 'online', NULL, NULL, 'Dhaka', 80, 15, 50, 450, NULL, 4.4, 156, '📋', 'survey,research,opinion', 'open', 0, 0, 24),
(35, 'Fintech Mobile App UX Feedback', 'Test our new payment checkout screen. Complete 3 tasks on the staging app and record 2-minute voice/video feedback explaining confusion points or lag.', 38, 10, 'online', NULL, NULL, 'Dhaka', 150, 15, 50, 450, NULL, 4.9, 33, '💡', 'ux,feedback,opinion,fintech', 'open', 0, 0, 12)
